// A refused mailbox stays refused; another try would only repeat the warning.\n            tracing::warn!(subscription = ctx.name(), %error, \"notice not sent\");\n            return Err(HandlerOutcome::drop());\n        }\n        Ok(())\n    }\n}\n"})})})]}),"\n",(0,a.jsxs)(t.p,{children:["\u5728\u624B\u5199\u5F62\u5F0F\u4E2D\uFF0C\u72B6\u6001\u7C7B\u578B\u662F ",(0,a.jsx)(t.code,{children:"Handle"})," \u7684\u6700\u540E\u4E00\u4E2A\u53C2\u6570\uFF0C\u6302\u8F7D\u65F6\u4F1A\u628A\u5B83\u4E0E\u5E94\u7528\u7684\u72B6\u6001\u7C7B\u578B\u6838\u5BF9\u3002\n\u4E3B\u4F53\u7528 ",(0,a.jsx)(t.a,{href:"https://docs.rs/ruststream/0.7/ruststream/runtime/trait.FromContext.html",children:(0,a.jsx)(t.code,{children:"from_context"})})," \u8BFB\u53D6\u5B57\u6BB5\uFF0C\u8FD9\u6B63\u662F\u5B8F\u5BF9 ",(0,a.jsx)(t.code,{children:"State"})," \u53C2\u6570\u6240\u505A\u7684\u4E8B\u3002\n",(0,a.jsx)(t.a,{href:"/components/subscribers/context/from-context/",children:"\u81EA\u5B9A\u4E49\u63D0\u53D6\u5668"}),"\u662F\u4F60\u81EA\u5DF1\u7684\u7C7B\u578B\uFF0C\u4EE5\u540C\u6837\u7684\u65B9\u5F0F\u8BFB\u53D6\u3002"]})]})}function p(e={}){let{wrapper:t}={...(0,s.R)(),...e.components};return t?(0,a.jsx)(t,{...e,children:(0,a.jsx)(h,{...e})}):h(e)}},57250(e,t,r){r.d(t,{A:()=>l});var n=r(74848);r(96540);var a=r(34164),s=r(57663);function i({children:e,className:t,hidden:r}){return(0,n.jsx)("div",{role:"tabpanel",className:(0,a.A)("tabItem_Ymn6",t),hidden:r,children:e})}function l({children:e,className:t,value:r}){let{selectedValue:a,lazy:o}=(0,s.uc)(),c=r===a;return!c&&o?null:(0,n.jsx)(i,{className:t,hidden:!c,children:e})}},50773(e,t,r){r.d(t,{A:()=>h});var n=r(74848);r(96540);var a=r(34164),s=r(88287),i=r(57663),l=r(28584),o=r(19863);function c({className:e}){let{selectedValue:t,selectValue:r,tabValues:s,block:o}=(0,i.uc)(),u=[],{blockElementScrollPositionUntilNextRender:d}=(0,l.a_)(),h=e=>{let n=e.currentTarget,a=s[u.indexOf(n)].value;a!==t&&(d(n),r(a))},p=e=>{let t=null;switch(e.key){case"Ente